class Solution:
    def firstMissingPositive(self, nums: List[int]) -> int:
        n = len(nums)
        # 清除负值
        for i in range(n):
            if nums[i] <= 0:
                nums[i] = n + 1

        # 利用正值进行负值哈希
        for i in range(n):
            num = abs(nums[i])
            if num <= n:
                nums[num - 1] = -abs(nums[num - 1])

        # 第一个不是负值
        for i in range(n):
            if nums[i] > 0:
                return i + 1

        # 按顺序全部有, 那就肯定是更大的
        return n + 1
